55			incrementAge();
56			incrementHunger();
57			battleSickness();
58			if (isAlive()) {
59				boolean shouldAct = (time == TimeCycle.NIGHT && isNocturnal())
60						|| (time == TimeCycle.DAY && !isNocturnal());
61				if (shouldAct) {
62					normalAct(newAnimals);
63				}
64			}
65		}
