76		private boolean canBreed() {
77			if (age < getBreedingAge()) {
78				return false;
79			}
80			Field field = getField();
81			List<Location> adjacent = field.adjacentAnimalLocations(getLocation());
82			for (Location where : adjacent) {
83				Object animal = field.getAnimalAt(where);
84				if (animal instanceof Animal) {
85					Animal animalNear = (Animal) animal;
86					if (animalNear.getClass() == this.getClass() && getGender() != animalNear.getGender()) {
87						return true;
88					}
89				}
90			}
91			return false;
92		}
