104	
105	
106			if (getGender() == Gender.FEMALE) {
107				Field field = getField();
108				List<Location> free = field.getFreeAnimalAdjacentLocations(getLocation());
109				int births = breed();
110				for (int b = 0; b < births && !free.isEmpty(); b++) {
111					Location loc = free.remove(0);
112					Animal young = createNewAnimal(false, field, loc);
113					newAnimals.add(young);
114				}
115			}
116		}
