159				}
160				sickStep++;
161				Field field = getField();
162				if (field != null) {
163					for (Location where : field.adjacentAnimalLocations(getLocation())) {
164						Object animal = field.getAnimalAt(where);
165						if (animal instanceof Animal) {
166							Animal nearAnimal = (Animal) animal;
167							if (nearAnimal.getClass() == this.getClass()) {
168								nearAnimal.becomeSick();
169							}
170						}
171					}
172					notSick();
173				}
174			} else {
175				becomeSick();
176			}
177		}
