6	
7	public class Field {
8	
9		private static final Random rand = Randomizer.getRandom();
10	
11	
12		private int depth, width;
13	
14		private Object[][] animalField;
15	
16		private Object[][] plantField;
17	
18	
19		public Field(int depth, int width) {
20			this.depth = depth;
21			this.width = width;
22			animalField = new Object[depth][width];
23			plantField = new Object[depth][width];
24		}
25	
26	
27		public void clear() {
28			for (int row = 0; row < depth; row++) {
29				for (int col = 0; col < width; col++) {
30					animalField[row][col] = null;
31					plantField[row][col] = null;
32				}
33			}
34		}
35	
36	
37		public void clear(Location location) {
38			animalField[location.getRow()][location.getCol()] = null;
39		}
40	
41	
42		public void placeAnimal(Object animal, Location location) {
43			animalField[location.getRow()][location.getCol()] = animal;
44		}
45	
46	
47		public void placePlant(Object plant, Location location) {
48			plantField[location.getRow()][location.getCol()] = plant;
49		}
50	
51	
52		public Object getAnimalAt(Location location) {
53			return getAnimalAt(location.getRow(), location.getCol());
54		}
55	
56	
57		public Object getAnimalAt(int row, int col) {
58			return animalField[row][col];
59		}
60	
61	
62		public Object getPlantAt(Location location) {
63			return getPlantAt(location.getRow(), location.getCol());
64		}
65	
66	
67		public Object getPlantAt(int row, int col) {
68			return plantField[row][col];
69		}
70	
71	
72		public List<Location> getFreeAnimalAdjacentLocations(Location location) {
73			List<Location> free = new LinkedList<>();
74			List<Location> adjacent = adjacentAnimalLocations(location);
75			for (Location next : adjacent) {
76				if (getAnimalAt(next) == null) {
77					free.add(next);
78				}
79			}
80			return free;
81		}
82	
83	
84		public Location freeAnimalAdjacentLocation(Location location) {
85			List<Location> free = getFreeAnimalAdjacentLocations(location);
86			return free.isEmpty() ? null : free.get(0);
87		}
88	
89	
90		public List<Location> adjacentAnimalLocations(Location location) {
91			assert location != null : "Null location passed to adjacentLocations";
92	
93			List<Location> locations = new LinkedList<>();
94			int row = location.getRow();
95			int col = location.getCol();
96			for (int roffset = -1; roffset <= 1; roffset++) {
97				int nextRow = row + roffset;
98				if (nextRow >= 0 && nextRow < depth) {
99					for (int coffset = -1; coffset <= 1; coffset++) {
100						int nextCol = col + coffset;
101						if (nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) {
102							locations.add(new Location(nextRow, nextCol));
103						}
104					}
105				}
106			}
107			Collections.shuffle(locations, rand);
108			return locations;
109		}
110	
111	
112		public int getDepth() {
113			return depth;
114		}
115	
116	
117		public int getWidth() {
118			return width;
119		}
120	}
