1	import java.util.HashMap;
2	
3	
4	public class FieldStats {
5	
6		private HashMap<Class<?>, Counter> counters;
7	
8		private boolean countsValid;
9	
10	
11		public FieldStats() {
12	
13	
14			counters = new HashMap<>();
15			countsValid = true;
16		}
17	
18	
19		public String getPopulationDetails(Field field) {
20			StringBuilder buffer = new StringBuilder();
21			if (!countsValid) {
22				generateCounts(field);
23			}
24			for (Counter info : counters.values()) {
25				buffer.append(info.getName());
26				buffer.append(": ");
27				buffer.append(info.getCount());
28				buffer.append(' ');
29			}
30			return buffer.toString();
31		}
32	
33	
34		public void reset() {
35			countsValid = false;
36			for (Counter count : counters.values()) {
37				count.reset();
38			}
39		}
40	
41	
42		public void incrementCount(Class<?> animalClass) {
43			Counter count = counters.get(animalClass);
44			if (count == null) {
45				count = new Counter(animalClass.getSimpleName());
46				counters.put(animalClass, count);
47			}
48			count.increment();
49		}
50	
51	
52		public void countFinished() {
53			countsValid = true;
54		}
55	
56	
57		public boolean isViable(Field field) {
58			int nonZero = 0;
59			if (!countsValid) {
60				generateCounts(field);
61			}
62			for (Counter info : counters.values()) {
63				if (info.getCount() > 0) {
64					nonZero++;
65				}
66			}
67			return nonZero > 1;
68		}
69	
70	
71		private void generateCounts(Field field) {
72			reset();
73			for (int row = 0; row < field.getDepth(); row++) {
74				for (int col = 0; col < field.getWidth(); col++) {
75					Object animal = field.getAnimalAt(row, col);
76					if (animal != null) {
77						incrementCount(animal.getClass());
78					}
79				}
80			}
81			countsValid = true;
82		}
83	
84	
85		public int getPopulationCount(Field field, Class<?> key) {
86			if (!countsValid) {
87				generateCounts(field);
88			}
89			Counter counter = counters.get(key);
90			return counter == null ? 0 : counter.getCount();
91		}
92	}
