84		class GraphPanel extends JComponent {
85			private static final double SCALE_FACTOR = 0.8;
86	
87	
88			private BufferedImage graphImage;
89			private int[] lastVal;
90			private int yMax;
91	
92	
93			public GraphPanel(int width, int height, int startMax) {
94				graphImage = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
95				clearImage();
96				lastVal = new int[classes.size()];
97				Arrays.fill(lastVal, height);
98				yMax = startMax;
99			}
100	
101	
102			public void newRun() {
103				int height = graphImage.getHeight();
104				int width = graphImage.getWidth();
105	
106				Graphics g = graphImage.getGraphics();
107				g.copyArea(4, 0, width - 4, height, -4, 0);
108				g.setColor(Color.BLACK);
109				g.drawLine(width - 4, 0, width - 4, height);
110				g.drawLine(width - 2, 0, width - 2, height);
111				lastVal = new int[classes.size()];
112				Arrays.fill(lastVal, height);
113				repaint();
114			}
115	
116	
117			public void update(int step, Field field, FieldStats stats) {
118	
119				Graphics g = graphImage.getGraphics();
120	
121				int height = graphImage.getHeight();
122				int width = graphImage.getWidth();
123	
124	
125				g.copyArea(1, 0, width - 1, height, -1, 0);
126	
127				stats.reset();
128	
129				int i = 0;
130				for (Iterator<Class<?>> it = classes.iterator(); it.hasNext(); i++) {
131					Class<?> nextClass = it.next();
132					int count = stats.getPopulationCount(field, nextClass);
133	
134	
135					int y = height - ((height * count) / yMax) - 1;
136					while (y < 0) {
137						scaleDown();
138						y = height - ((height * count) / yMax) - 1;
139					}
140					g.setColor(LIGHT_GRAY);
141					g.drawLine(width - 2, y, width - 2, height);
142					g.setColor(colors.get(nextClass));
143					g.drawLine(width - 3, lastVal[i], width - 2, y);
144					lastVal[i] = y;
145				}
146	
147				repaint();
148	
149				stepLabel.setText(String.valueOf(step));
150				countLabel.setText(stats.getPopulationDetails(field));
151	
152			}
153	
154	
155			public void scaleDown() {
156				Graphics g = graphImage.getGraphics();
157				int height = graphImage.getHeight();
158				int width = graphImage.getWidth();
159	
160				BufferedImage tmpImage = new BufferedImage(width, (int) (height * SCALE_FACTOR),
161						BufferedImage.TYPE_INT_RGB);
162				Graphics2D gtmp = (Graphics2D) tmpImage.getGraphics();
163	
164				gtmp.scale(1.0, SCALE_FACTOR);
165				gtmp.drawImage(graphImage, 0, 0, null);
166	
167				int oldTop = (int) (height * (1.0 - SCALE_FACTOR));
168	
169				g.setColor(Color.WHITE);
170				g.fillRect(0, 0, width, oldTop);
171				g.drawImage(tmpImage, 0, oldTop, null);
172	
173				yMax = (int) (yMax / SCALE_FACTOR);
174	
175				for (int i = 0; i < lastVal.length; i++) {
176					lastVal[i] = oldTop + (int) (lastVal[i] * SCALE_FACTOR);
177				}
178	
179				repaint();
180			}
181	
182	
183			public final void clearImage() {
184				Graphics g = graphImage.getGraphics();
185				g.setColor(Color.WHITE);
186				g.fillRect(0, 0, graphImage.getWidth(), graphImage.getHeight());
187				repaint();
188			}
189	
190	
191			public Dimension getPreferredSize() {
192				return new Dimension(graphImage.getWidth(), graphImage.getHeight());
193			}
194	
195	
196			public boolean isOpaque() {
197				return true;
198			}
199	
200	
201			public void paintComponent(Graphics g) {
202				if (graphImage != null) {
203					g.drawImage(graphImage, 0, 0, null);
204				}
205			}
206		}
207	}
