5	public abstract class Predator extends Animal {
6	
7	
8		private static final Random rand = Randomizer.getRandom();
9	
10		private boolean cannibal;
11	
12		private int additionalFoodValue;
13	
14	
15		public Predator(boolean randomAge, Field field, Location location) {
16			super(field, location);
17			if (randomAge) {
18				setAge(rand.nextInt(getMaxAge()));
19				setFoodLevel(rand.nextInt(5));
20			} else {
21				setAge(0);
22				setFoodLevel(6);
23			}
24			cannibal = false;
25			additionalFoodValue = 0;
26			setMaxSickStep(30);
27		}
28	
29	
30		protected void normalAct(List<Animal> newAnimals) {
31			giveBirth(newAnimals);
32	
33			Location newLocation = findFood();
34			if (isAlive()) {
35				if (newLocation == null) {
36					newLocation = getField().freeAnimalAdjacentLocation(getLocation());
37				}
38				if (newLocation != null) {
39					setLocation(newLocation);
40				} else {
41					setDead();
42				}
43			}
44		}
45	
46	
47		private Location findFood() {
48			Field field = getField();
49			for (Location where : field.adjacentAnimalLocations(getLocation())) {
50				Object animal = field.getAnimalAt(where);
51				if (animal instanceof Animal) {
52					Animal nearAnimal = (Animal) animal;
53	
54					if (nearAnimal.getFoodChainLevel() < getFoodChainLevel() && nearAnimal.isAlive()) {
55						nearAnimal.setDead();
56						setFoodLevel(nearAnimal.getFoodValue() + additionalFoodValue);
57						return where;
58					}
59	
60					if (nearAnimal.getFoodChainLevel() == getFoodChainLevel()
61							&& nearAnimal.isAlive() && isCannibal()
62							&& getFoodLevel() < 2 && nearAnimal.getClass() == this.getClass()) {
63						nearAnimal.setDead();
64						setFoodLevel(nearAnimal.getFoodValue() + additionalFoodValue);
65						return where;
66					}
67				}
68			}
69			return null;
70		}
71	
72	
73		public boolean isCannibal() {
74			return cannibal;
75		}
76	
77	
78		public void toggleCannibal() {
79			cannibal = !cannibal;
80		}
81	
82	
83		protected void setAdditionalFoodValue(int inputValue) {
84			additionalFoodValue = inputValue;
85		}
86	}
