1	import java.util.ArrayList;
2	import java.util.Iterator;
3	import java.util.List;
4	import java.util.Random;
5	
6	
7	public class Simulator {
8	
9	
10		private static final int DEFAULT_WIDTH = 320;
11	
12		private static final int DEFAULT_DEPTH = 200;
13	
14		private static final double FLOWER_CREATION_PROBABILITY = 0.07;
15	
16		private static final double MOUSE_CREATION_PROBABILITY = 0.07;
17	
18		private static final double DUCK_CREATION_PROBABILITY = 0.07;
19	
20		private static final double BIRD_CREATION_PROBABILITY = 0.07;
21	
22		private static final double WOLF_CREATION_PROBABILITY = 0.03;
23	
24		private static final double BEAR_CREATION_PROBABILITY = 0.03;
25	
26		private static final TimeCycle DEFAULT_TIMECYCLE = TimeCycle.DAY;
27	
28		private static final Weather DEFAULT_WEATHER = Weather.SUN;
29	
30		private static final int TIMECYCLE_LENGTH = 4;
31	
32	
33		private List<Animal> animals;
34	
35		private List<Plant> plants;
36	
37		private Field field;
38	
39		private int step;
40	
41		private SimulatorView gridView;
42	
43		private GraphView graphView;
44	
45		private TimeCycle currentTimeCycle;
46	
47		private Climate climate;
48	
49		private int sickPercentage;
50	
51	
52		public Simulator() {
53			this(DEFAULT_DEPTH, DEFAULT_WIDTH);
54		}
55	
56	
57		public Simulator(int depth, int width) {
58			if (width <= 0 || depth <= 0) {
59				System.out.println("The dimensions must be greater than zero.");
60				System.out.println("Using default values.");
61				depth = DEFAULT_DEPTH;
62				width = DEFAULT_WIDTH;
63			}
64	
65	
66			animals = new ArrayList<>();
67	
68			plants = new ArrayList<>();
69			field = new Field(depth, width);
70			climate = new Climate(DEFAULT_WEATHER);
71	
72	
73			gridView = new SimulatorView(depth, width);
74	
75	
76			graphView = new GraphView(1000, 500, 500);
77	
78	
79			reset();
80		}
81	
82	
83		public void runLongSimulation() {
84			simulate(4000);
85		}
86	
87	
88		public void simulate(int numSteps) {
89			for (int step = 1; step <= numSteps && gridView.isViable(field); step++) {
90				simulateOneStep();
91				delay(60);
92			}
93		}
94	
95	
96		public void simulateOneStep() {
97			step++;
98			climate.updateClimate(step);
99	
100	
101			for (Plant plant : plants) {
102				plant.increaseStage(climate);
103			}
104	
105	
106			List<Animal> newAnimals = new ArrayList<>();
107	
108			for (Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
109				Animal animal = it.next();
110				animal.act(newAnimals, currentTimeCycle);
111				if (!animal.isAlive()) {
112					it.remove();
113				}
114			}
115	
116	
117			animals.addAll(newAnimals);
118	
119	
120			if (step % TIMECYCLE_LENGTH == 0) {
121				currentTimeCycle = currentTimeCycle.toggle();
122			}
123	
124	
125			int count = 0;
126			for (Animal i : animals) {
127				if (i.isSick()) {
128					count++;
129				}
130			}
131	
132			sickPercentage = animals.isEmpty() ? 0 : (count * 100) / animals.size();
133			gridView.showStatus(step, currentTimeCycle, field, climate, sickPercentage);
134			graphView.showStatus(step, field);
135		}
136	
137	
138		public void reset() {
139			step = 0;
140			animals.clear();
141			populate();
142			currentTimeCycle = DEFAULT_TIMECYCLE;
143			climate.setCurrentWeather(Weather.SUN);
144	
145			sickPercentage = 0;
146			graphView.reset();
147			gridView.showStatus(step, currentTimeCycle, field, climate, sickPercentage);
148			graphView.showStatus(step, field);
149		}
150	
151	
152		private void populate() {
153			Random rand = Randomizer.getRandom();
154			field.clear();
155	
156			double mouseThreshold = BIRD_CREATION_PROBABILITY + MOUSE_CREATION_PROBABILITY;
157			double duckThreshold = mouseThreshold + DUCK_CREATION_PROBABILITY;
158			double wolfThreshold = duckThreshold + WOLF_CREATION_PROBABILITY;
159			double bearThreshold = wolfThreshold + BEAR_CREATION_PROBABILITY;
160	
161			for (int row = 0; row < field.getDepth(); row++) {
162				for (int col = 0; col < field.getWidth(); col++) {
163					Location location = new Location(row, col);
164	
165					if (rand.nextDouble() <= FLOWER_CREATION_PROBABILITY) {
166						Flower flower = new Flower(field, location);
167						plants.add(flower);
168					} else {
169						Grass grass = new Grass(field, location);
170						plants.add(grass);
171					}
172	
173					double animalRoll = rand.nextDouble();
174					if (animalRoll < BIRD_CREATION_PROBABILITY) {
175						Bird bird = new Bird(true, field, location);
176						animals.add(bird);
177						graphView.setColor(Bird.class, bird.getObjectColor(climate));
178					} else if (animalRoll < mouseThreshold) {
179						Mouse mouse = new Mouse(true, field, location);
180						animals.add(mouse);
181						graphView.setColor(Mouse.class, mouse.getObjectColor(climate));
182					} else if (animalRoll < duckThreshold) {
183						Duck duck = new Duck(true, field, location);
184						animals.add(duck);
185						graphView.setColor(Duck.class, duck.getObjectColor(climate));
186					} else if (animalRoll < wolfThreshold) {
187						Wolf wolf = new Wolf(true, field, location);
188						animals.add(wolf);
189						graphView.setColor(Wolf.class, wolf.getObjectColor(climate));
190					} else if (animalRoll < bearThreshold) {
191						Bear bear = new Bear(true, field, location);
192						animals.add(bear);
193						graphView.setColor(Bear.class, bear.getObjectColor(climate));
194					}
195				}
196			}
197		}
198	
199	
200		private void delay(int millisec) {
201			try {
202				Thread.sleep(millisec);
203			} catch (InterruptedException ie) {
204				Thread.currentThread().interrupt();
205			}
206		}
207	}
