4	
5	public class SimulatorView extends JFrame {
6	
7		private static final Color EMPTY_COLOR = Color.white;
8	
9		private static final String STEP_PREFIX = "Step: ";
10		private static final String POPULATION_PREFIX = "Population: ";
11		private static final String DAYCYCLE_PREFIX = "Day cycle: ";
12		private static final String CLIMATE_PREFIX = "Season: ";
13		private static final String WEATHER_PREFIX = "Weather: ";
14		private static final String INFECTION_PREFIX = "Infection: ";
15		private static final String HUMIDITY_PREFIX = "Humidity: ";
16	
17		private JLabel stepLabel, populationLabel, dayCycleLabel, climateLabel, infectLabel, weatherLabel, humidityLabel;
18		private FieldView fieldView;
19	
20		private FieldStats stats;
21	
22	
23		public SimulatorView(int height, int width) {
24			stats = new FieldStats();
25	
26			setTitle("Predator-Prey Simulation");
27			stepLabel = new JLabel(STEP_PREFIX, JLabel.CENTER);
28			populationLabel = new JLabel(POPULATION_PREFIX, JLabel.CENTER);
29			dayCycleLabel = new JLabel(DAYCYCLE_PREFIX, JLabel.CENTER);
30			climateLabel = new JLabel(CLIMATE_PREFIX, JLabel.CENTER);
31			weatherLabel = new JLabel(WEATHER_PREFIX, JLabel.CENTER);
32			infectLabel = new JLabel(INFECTION_PREFIX, JLabel.CENTER);
33			humidityLabel = new JLabel(HUMIDITY_PREFIX, JLabel.CENTER);
34	
35			setLocation(100, 50);
36	
37			fieldView = new FieldView(height, width);
38	
39			Container contents = getContentPane();
40	
41			JPanel infoPane = new JPanel(new FlowLayout());
42			JPanel detailPane = new JPanel(new BorderLayout());
43	
44			infoPane.add(stepLabel);
45			infoPane.add(dayCycleLabel);
46			infoPane.add(climateLabel);
47			infoPane.add(weatherLabel);
48			infoPane.add(humidityLabel);
49			infoPane.add(infectLabel);
50			contents.add(infoPane, BorderLayout.NORTH);
51			contents.add(fieldView, BorderLayout.CENTER);
52			contents.add(detailPane, BorderLayout.SOUTH);
53			detailPane.add(populationLabel, BorderLayout.CENTER);
54	
55			pack();
56			setVisible(true);
57		}
58	
59	
60		public void showStatus(int step, TimeCycle currentTimeCycle, Field field, Climate climate, int infect) {
61			if (!isVisible()) {
62				setVisible(true);
63			}
64	
65			stepLabel.setText(STEP_PREFIX + step);
66			dayCycleLabel.setText(DAYCYCLE_PREFIX + currentTimeCycle + " ");
67			climateLabel.setText(CLIMATE_PREFIX + climate.getCurrentSeason());
68			weatherLabel.setText(WEATHER_PREFIX + climate.getCurrentWeather());
69			infectLabel.setText(INFECTION_PREFIX + infect + "%");
70			humidityLabel.setText(HUMIDITY_PREFIX + climate.getHumidity() + "%");
71			stats.reset();
72	
73			fieldView.preparePaint();
74	
75	
76			for (int row = 0; row < field.getDepth(); row++) {
77				for (int col = 0; col < field.getWidth(); col++) {
78					Object animalObj = field.getAnimalAt(row, col);
79					Object plantObj = field.getPlantAt(row, col);
80					if (animalObj instanceof Animal) {
81						Animal animal = (Animal) animalObj;
82						stats.incrementCount(animal.getClass());
83						fieldView.drawMark(col, row, animal.getObjectColor(climate));
84					} else if (plantObj instanceof Plant) {
85						fieldView.drawMark(col, row, ((Plant) plantObj).getObjectColor(climate));
86					} else {
87						fieldView.drawMark(col, row, EMPTY_COLOR);
88					}
89				}
90			}
91			stats.countFinished();
92	
93			populationLabel.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
94			fieldView.repaint();
95		}
96	
97	
98		public boolean isViable(Field field) {
99			return stats.isViable(field);
100		}
