103		private class FieldView extends JPanel {
104			private static final int GRID_VIEW_SCALING_FACTOR = 5;
105			private Dimension size;
106			private int gridWidth, gridHeight;
107			private int xScale, yScale;
108			private Graphics g;
109			private Image fieldImage;
110	
111	
112			public FieldView(int height, int width) {
113				gridHeight = height;
114				gridWidth = width;
115				size = new Dimension(0, 0);
116			}
117	
118	
119			public Dimension getPreferredSize() {
120				return new Dimension(gridWidth * GRID_VIEW_SCALING_FACTOR,
121						gridHeight * GRID_VIEW_SCALING_FACTOR);
122			}
123	
124	
125			public void preparePaint() {
126				if (!size.equals(getSize())) {
127					size = getSize();
128					fieldImage = fieldView.createImage(size.width, size.height);
129					g = fieldImage.getGraphics();
130	
131					xScale = size.width / gridWidth;
132					if (xScale < 1) {
133						xScale = GRID_VIEW_SCALING_FACTOR;
134					}
135					yScale = size.height / gridHeight;
136					if (yScale < 1) {
137						yScale = GRID_VIEW_SCALING_FACTOR;
138					}
139				}
140			}
141	
142	
143			public void drawMark(int x, int y, Color color) {
144				g.setColor(color);
145				g.fillRect(x * xScale, y * yScale, xScale - 1, yScale - 1);
146				g.drawRect(x * xScale, y * yScale, xScale - 1, yScale - 1);
147			}
148	
149	
150			public void paintComponent(Graphics g) {
151				if (fieldImage != null) {
152					Dimension currentSize = getSize();
153					if (size.equals(currentSize)) {
154						g.drawImage(fieldImage, 0, 0, null);
155					} else {
156	
157						g.drawImage(fieldImage, 0, 0, currentSize.width, currentSize.height, null);
158					}
159				}
160			}
161		}
162	}
