3	
4	
5	public class Grass extends Plant {
6	
7		private static final Random rand = Randomizer.getRandom();
8	
9	
10		public Grass(Field field, Location location) {
11			super(field, location);
12	
13	
14			double stageRoll = rand.nextDouble();
15			if (stageRoll < 0.5) {
16				setMaxStage(3);
17			} else if (stageRoll < 0.8) {
18				setMaxStage(2);
19			} else {
20				setMaxStage(1);
21			}
22			setStage(getMaxStage());
23		}
24	
25	
26		protected void increaseStage(Climate climate) {
27			super.increaseStage(climate);
28			if (climate.getCurrentSeason() == Season.SPRING && getStage() > 2) {
29				setStage(2);
30			} else if (climate.getCurrentSeason() == Season.SUMMER && getStage() > 3) {
31				setStage(3);
32			} else if (climate.getCurrentSeason() == Season.AUTUMN && getStage() > 2) {
33				setStage(2);
34			} else if (climate.getCurrentSeason() == Season.WINTER && getStage() > 1) {
35				setStage(1);
36			}
37		}
38	
39	
40		protected Color getObjectColor(Climate climate) {
41			switch (climate.getCurrentSeason()) {
42				case SPRING:
43					if (getStage() == 2) {
44						return new Color(34, 140, 61);
45					} else if (getStage() == 1) {
46						return new Color(68, 201, 104);
47					} else {
48						return new Color(131, 101, 57);
49					}
50				case SUMMER:
51					if (getStage() == 3) {
52						return new Color(11, 102, 35);
53					} else if (getStage() == 2) {
