	public void act(List<Animal> newAnimals, TimeCycle time) {
		incrementAge();
		incrementHunger();
		battleSickness();
		if (isAlive()) {
			boolean shouldAct = (time == TimeCycle.NIGHT && isNocturnal())
					|| (time == TimeCycle.DAY && !isNocturnal());
